const input = $input.first().json;

const well_id = String(
  input.well_id ??
  input['Идентификатор скважины'] ??
  ''
).trim();

const rawHorizon =
  input.horizon_days ??
  input['Горизонт прогноза, дней'] ??
  90;

const horizon_days = rawHorizon === '' ? 90 : Number(rawHorizon);

if (!well_id) {
  throw new Error('Укажите идентификатор скважины.');
}

if (!Number.isInteger(horizon_days) || horizon_days < 1 || horizon_days > 3650) {
  throw new Error('Горизонт должен быть целым числом от 1 до 3650 дней.');
}

return [
  {
    json: {
      well_id,
      horizon_days
    }
  }
];
